#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("NO_INPUT\n");
        return 0;
    }
    long num = strtol(argv[1], NULL, 10);
    if (num < 0 || num > 1000000000) {
        printf("OUT_OF_RANGE\n");
        return 0;
    }
    for (long i = 2; i * i <= num; i++) {
        int count = 0;
        while (num % i == 0) {
            count++;
            num /= i;
        }
        if (count > 0) {
            if (count == 1) {
                printf("%ld^1 ", i);
            } else {
                printf("%ld^%d ", i, count);
            }
        }
    }
    if (num > 1) {
        printf("%ld^1\n", num);
    } else {
        printf("\n");
    }
    return 0;
}
